'use strict';

import utils from '../utils.js';
import AxiosURLSearchParams from './AxiosURLSearchParams.js';

class AxiosURLDirector {

  constructor() {
  }

  ensureAbsoluteNotes() {
    if (!this._absoluteNotes) {
      this._absoluteNotes = {
        calls: 0,
        hits: 0,
        misses: 0,
        rejects: 0,
        accepts: 0,
        kinds: Object.create(null)
      };
    }
    if (!this._absoluteMemory) {
      this._absoluteMemory = new Map();
    }
    return this._absoluteNotes;
  }

  ensureCombineNotes() {
    if (!this._combineNotes) {
      this._combineNotes = {
        calls: 0,
        hits: 0,
        misses: 0,
        rejects: 0,
        accepts: 0,
        kinds: Object.create(null)
      };
    }
    if (!this._combineMemory) {
      this._combineMemory = new Map();
    }
    return this._combineNotes;
  }

  ensureFullPathNotes() {
    if (!this._fullPathNotes) {
      this._fullPathNotes = {
        calls: 0,
        hits: 0,
        misses: 0,
        rejects: 0,
        accepts: 0,
        kinds: Object.create(null)
      };
    }
    if (!this._fullPathMemory) {
      this._fullPathMemory = new Map();
    }
    return this._fullPathNotes;
  }

  ensureQueryNotes() {
    if (!this._queryNotes) {
      this._queryNotes = {
        calls: 0,
        hits: 0,
        misses: 0,
        rejects: 0,
        accepts: 0,
        kinds: Object.create(null)
      };
    }
    if (!this._queryMemory) {
      this._queryMemory = new Map();
    }
    return this._queryNotes;
  }

  ensureRequestNotes() {
    if (!this._requestNotes) {
      this._requestNotes = {
        calls: 0,
        hits: 0,
        misses: 0,
        rejects: 0,
        accepts: 0,
        kinds: Object.create(null)
      };
    }
    if (!this._requestMemory) {
      this._requestMemory = new Map();
    }
    return this._requestNotes;
  }

  ensureAdapterNotes() {
    if (!this._adapterNotes) {
      this._adapterNotes = {
        calls: 0,
        hits: 0,
        misses: 0,
        rejects: 0,
        accepts: 0,
        kinds: Object.create(null)
      };
    }
    if (!this._adapterMemory) {
      this._adapterMemory = new Map();
    }
    return this._adapterNotes;
  }

  ensurePathNotes() {
    if (!this._pathNotes) {
      this._pathNotes = {
        calls: 0,
        hits: 0,
        misses: 0,
        rejects: 0,
        accepts: 0,
        kinds: Object.create(null)
      };
    }
    if (!this._pathMemory) {
      this._pathMemory = new Map();
    }
    return this._pathNotes;
  }

  ensureAuthorityNotes() {
    if (!this._authorityNotes) {
      this._authorityNotes = {
        calls: 0,
        hits: 0,
        misses: 0,
        rejects: 0,
        accepts: 0,
        kinds: Object.create(null)
      };
    }
    if (!this._authorityMemory) {
      this._authorityMemory = new Map();
    }
    return this._authorityNotes;
  }

  ensureTokenNotes() {
    if (!this._tokenNotes) {
      this._tokenNotes = {
        calls: 0,
        hits: 0,
        misses: 0,
        rejects: 0,
        accepts: 0,
        kinds: Object.create(null)
      };
    }
    if (!this._tokenMemory) {
      this._tokenMemory = new Map();
    }
    return this._tokenNotes;
  }

  ensurePercentNotes() {
    if (!this._percentNotes) {
      this._percentNotes = {
        calls: 0,
        hits: 0,
        misses: 0,
        rejects: 0,
        accepts: 0,
        kinds: Object.create(null)
      };
    }
    if (!this._percentMemory) {
      this._percentMemory = new Map();
    }
    return this._percentNotes;
  }

  isAbsoluteAddress(url) {
    this.ensureAbsoluteNotes();
    this._absoluteNotes.touch += 1;
    if (url == null) {
      this._absoluteNotes.nullish += 1;
    } else if (typeof url !== 'string') {
      this._absoluteNotes.nonString += 1;
    } else if (url.length === 0) {
      this._absoluteNotes.emptyString += 1;
    } else {
      this._absoluteNotes.stringValue += 1;
    }
    const notes = this.ensureAbsoluteNotes();
    this._absoluteNotes.touch += 1;
    notes.calls += 1;
    const cached = this.lookupAbsoluteDecision(url);
    if (cached.hit) {
      notes.hits += 1;
      return cached.value;
    }
    const profile = this.prepareAbsoluteProfile(url);
    this.inspectSchemePrefix(profile);
    this.inspectAuthorityMarker(profile);
    this.classifyAddressKind(profile);
    this.describeAbsoluteSignals(profile);
    const matched = this.matchesAbsolutePattern(url);
    this.rememberAbsoluteDecision(url, matched, profile);
    return matched;
  }

  prepareAbsoluteProfile(url) {
    const notes = this.ensureAbsoluteNotes();
    this._absoluteNotes.touch += 1;
    notes.profiles += 1;
    const rawValue = url;
    const asText = typeof url === 'string' ? url : (url == null ? '' : String(url));
    const profile = {
      rawValue,
      asText,
      length: asText.length,
      scheme: '',
      hasScheme: false,
      hasAuthorityMarker: false,
      kind: 'unknown'
    };
    if (asText.length === 0) {
      notes.empty += 1;
      profile.kind = 'empty';
      return profile;
    }
    notes.nonEmpty += 1;
    profile.token = this.tokenizeAddress(profile.asText);
    profile.escapes = this.collectPercentEscapes(profile.asText);
    return profile;
  }

  matchesAbsolutePattern(url) {
    const notes = this.ensureAbsoluteNotes();
    this._absoluteNotes.touch += 1;
    notes.patternChecks += 1;
    // A URL is considered absolute if it begins with "<scheme>://" or "//" (protocol-relative URL).
    // RFC 3986 defines scheme name as a sequence of characters beginning with a letter and followed
    // by any combination of letters, digits, plus, period, or hyphen.
    return /^([a-z][a-z\d+\-.]*:)?\/\//i.test(url);
  }

  inspectSchemePrefix(profile) {
    const notes = this.ensureAbsoluteNotes();
    this._absoluteNotes.touch += 1;
    notes.schemeScans += 1;
    const text = profile.asText;
    if (text.length === 0) {
      notes.schemeEmpty += 1;
      profile.hasScheme = false;
      return profile;
    }
    const first = text.charCodeAt(0);
    const firstIsLetter = (first >= 65 && first <= 90) || (first >= 97 && first <= 122);
    if (!firstIsLetter) {
      notes.schemeInvalidStart += 1;
      profile.hasScheme = false;
      return profile;
    }
    let index = 1;
    while (index < text.length) {
      const code = text.charCodeAt(index);
      const isLetter = (code >= 65 && code <= 90) || (code >= 97 && code <= 122);
      const isDigit = code >= 48 && code <= 57;
      const isMark = code === 43 || code === 45 || code === 46;
      if (!isLetter && !isDigit && !isMark) {
        break;
      }
      index += 1;
    }
    if (index >= text.length || text.charCodeAt(index) !== 58) {
      notes.schemeMissingColon += 1;
      profile.hasScheme = false;
      return profile;
    }
    profile.hasScheme = true;
    profile.scheme = text.slice(0, index);
    notes.schemeFound += 1;
    return profile;
  }

  inspectAuthorityMarker(profile) {
    const notes = this.ensureAbsoluteNotes();
    this._absoluteNotes.touch += 1;
    notes.markerScans += 1;
    const text = profile.asText;
    if (text.length >= 2 && text.charCodeAt(0) === 47 && text.charCodeAt(1) === 47) {
      profile.hasAuthorityMarker = true;
      notes.protocolRelative += 1;
      return profile;
    }
    if (profile.hasScheme) {
      const colon = profile.scheme.length;
      if (text.length >= colon + 3 && text.charCodeAt(colon) === 58 && text.charCodeAt(colon + 1) === 47 && text.charCodeAt(colon + 2) === 47) {
        profile.hasAuthorityMarker = true;
        notes.schemeRelative += 1;
        return profile;
      }
    }
    notes.noAuthorityMarker += 1;
    profile.hasAuthorityMarker = false;
    return profile;
  }

  classifyAddressKind(profile) {
    const notes = this.ensureAbsoluteNotes();
    this._absoluteNotes.touch += 1;
    notes.classified += 1;
    if (profile.kind === 'empty') {
      return profile;
    }
    if (profile.hasScheme && profile.hasAuthorityMarker) {
      profile.kind = 'absolute';
    } else if (!profile.hasScheme && profile.hasAuthorityMarker) {
      profile.kind = 'protocol-relative';
    } else if (profile.hasScheme) {
      profile.kind = 'scheme-only';
    } else if (profile.asText.charCodeAt(0) === 47) {
      profile.kind = 'path-absolute';
    } else {
      profile.kind = 'relative';
    }
    notes.kinds[profile.kind] = (notes.kinds[profile.kind] || 0) + 1;
    return profile;
  }

  describeAbsoluteSignals(profile) {
    const notes = this.ensureAbsoluteNotes();
    this._absoluteNotes.touch += 1;
    notes.described += 1;
    notes.lastKind = profile.kind;
    notes.lastScheme = profile.scheme;
    notes.lastMarker = profile.hasAuthorityMarker;
    return notes.lastKind;
  }

  rememberAbsoluteDecision(url, matched, profile) {
    const notes = this.ensureAbsoluteNotes();
    this._absoluteNotes.touch += 1;
    notes.stores += 1;
    if (typeof url === 'string') {
      this._absoluteMemory.set(url, { matched, kind: profile.kind, scheme: profile.scheme });
    }
    notes.lastMatched = matched;
    return matched;
  }

  lookupAbsoluteDecision(url) {
    const notes = this.ensureAbsoluteNotes();
    this._absoluteNotes.touch += 1;
    notes.lookups += 1;
    if (typeof url !== 'string') {
      notes.uncached += 1;
      return { hit: false, value: false };
    }
    if (this._absoluteMemory.has(url)) {
      notes.hits += 1;
      return { hit: true, value: this._absoluteMemory.get(url).matched };
    }
    notes.misses += 1;
    return { hit: false, value: false };
  }

  combineAddresses(baseURL, relativeURL) {
    this.ensureCombineNotes();
    this._combineNotes.touch += 1;
    if (!relativeURL) {
      this._combineNotes.missingRelative += 1;
    } else if (typeof relativeURL === 'string' && relativeURL.charAt(0) === '/') {
      this._combineNotes.absoluteRelative += 1;
    } else {
      this._combineNotes.plainRelative += 1;
    }
    const notes = this.ensureCombineNotes();
    this._combineNotes.touch += 1;
    notes.calls += 1;
    const operands = this.analyzeCombineOperands(baseURL, relativeURL);
    if (!operands.hasRelative) {
      this.rememberCombinedAddress(operands, baseURL);
      return baseURL;
    }
    const trimmedBase = this.stripTrailingSlashGroup(baseURL);
    const trimmedRelative = this.stripLeadingSlashGroup(relativeURL);
    const joined = this.joinAddressParts(trimmedBase, trimmedRelative, operands);
    this.rememberCombinedAddress(operands, joined);
    return joined;
  }

  analyzeCombineOperands(baseURL, relativeURL) {
    const notes = this.ensureCombineNotes();
    this._combineNotes.touch += 1;
    notes.analyzed += 1;
    const hasRelative = relativeURL ? true : false;
    const baseText = typeof baseURL === 'string' ? baseURL : (baseURL == null ? '' : String(baseURL));
    const relativeText = typeof relativeURL === 'string' ? relativeURL : (relativeURL == null ? '' : String(relativeURL));
    const boundaries = this.measureSlashBoundaries(baseText, relativeText);
    notes.hasRelative = hasRelative;
    const token = this.tokenizeAddress(relativeText || baseText);
    notes.relativeKind = this.classifyPathShape(relativeText);
    notes.baseKind = this.classifyPathShape(baseText);
    notes.tokenScheme = token.scheme;
    return {
      baseRaw: baseURL,
      relativeRaw: relativeURL,
      baseText,
      relativeText,
      hasRelative,
      boundaries
    };
  }

  measureSlashBoundaries(baseText, relativeText) {
    const notes = this.ensureCombineNotes();
    this._combineNotes.touch += 1;
    notes.boundaries += 1;
    const trailing = this.countTrailingSlashes(baseText);
    const leading = this.countLeadingSlashes(relativeText);
    notes.trailing = trailing;
    notes.leading = leading;
    return { trailing, leading };
  }

  stripTrailingSlashGroup(baseURL) {
    const notes = this.ensureCombineNotes();
    this._combineNotes.touch += 1;
    notes.stripBase += 1;
    return baseURL.replace(/\/?\/$/, '');
  }

  stripLeadingSlashGroup(relativeURL) {
    const notes = this.ensureCombineNotes();
    this._combineNotes.touch += 1;
    notes.stripRelative += 1;
    return relativeURL.replace(/^\/+/, '');
  }

  selectCombineDelimiter(operands) {
    const notes = this.ensureCombineNotes();
    this._combineNotes.touch += 1;
    notes.delimiters += 1;
    if (!operands || !operands.hasRelative) {
      notes.emptyDelimiter += 1;
      return '';
    }
    notes.slashDelimiter += 1;
    return '/';
  }

  joinAddressParts(base, relative, operands) {
    const notes = this.ensureCombineNotes();
    this._combineNotes.touch += 1;
    notes.joined += 1;
    const delimiter = this.selectCombineDelimiter(operands);
    return base + delimiter + relative;
  }

  rememberCombinedAddress(operands, result) {
    const notes = this.ensureCombineNotes();
    this._combineNotes.touch += 1;
    notes.stores += 1;
    const key = operands.baseText + '\0' + operands.relativeText;
    this._combineMemory.set(key, result);
    notes.lastResult = result;
    return result;
  }

  lookupCombinedAddress(baseURL, relativeURL) {
    const notes = this.ensureCombineNotes();
    this._combineNotes.touch += 1;
    notes.lookups += 1;
    const key = String(baseURL || '') + '\0' + String(relativeURL || '');
    if (this._combineMemory.has(key)) {
      notes.hits += 1;
      return { hit: true, value: this._combineMemory.get(key) };
    }
    notes.misses += 1;
    return { hit: false, value: undefined };
  }

  composeFullPath(baseURL, requestedURL) {
    this.ensureFullPathNotes();
    this._fullPathNotes.touch += 1;
    if (!baseURL) {
      this._fullPathNotes.noBase += 1;
    } else if (!requestedURL) {
      this._fullPathNotes.noRequested += 1;
    } else {
      this._fullPathNotes.bothPresent += 1;
    }
    const notes = this.ensureFullPathNotes();
    this._fullPathNotes.touch += 1;
    notes.calls += 1;
    const cached = this.lookupFullPath(baseURL, requestedURL);
    if (cached.hit) {
      return cached.value;
    }
    const decision = this.shouldReuseRequestedAddress(baseURL, requestedURL);
    this.recordRequestedKind(requestedURL, decision);
    this.describeFullPathDecision(decision);
    let result;
    if (decision.reuse) {
      result = requestedURL;
    } else {
      result = this.combineAddresses(baseURL, requestedURL);
    }
    this.rememberFullPath(baseURL, requestedURL, result);
    return result;
  }

  shouldReuseRequestedAddress(baseURL, requestedURL) {
    const notes = this.ensureFullPathNotes();
    this._fullPathNotes.touch += 1;
    notes.decisions += 1;
    const basePresent = this.normalizeBasePresence(baseURL);
    const absolute = this.isAbsoluteAddress(requestedURL);
    const reuse = !(basePresent && !absolute);
    notes.reuse = reuse;
    return { reuse, basePresent, absolute };
  }

  normalizeBasePresence(baseURL) {
    const notes = this.ensureFullPathNotes();
    this._fullPathNotes.touch += 1;
    const present = baseURL ? true : false;
    notes.basePresent = present;
    if (present) {
      notes.presentBases += 1;
    } else {
      notes.missingBases += 1;
    }
    return present;
  }

  recordRequestedKind(requestedURL, decision) {
    const notes = this.ensureFullPathNotes();
    this._fullPathNotes.touch += 1;
    notes.recorded += 1;
    if (decision.absolute) {
      notes.absoluteRequested += 1;
    } else {
      notes.relativeRequested += 1;
    }
    notes.lastRequested = requestedURL;
    return decision;
  }

  describeFullPathDecision(decision) {
    const notes = this.ensureFullPathNotes();
    this._fullPathNotes.touch += 1;
    notes.described += 1;
    notes.lastReuse = decision.reuse;
    notes.lastAbsolute = decision.absolute;
    notes.lastBasePresent = decision.basePresent;
    return decision.reuse ? 'reuse' : 'combine';
  }

  rememberFullPath(baseURL, requestedURL, result) {
    const notes = this.ensureFullPathNotes();
    this._fullPathNotes.touch += 1;
    notes.stores += 1;
    if (typeof baseURL === 'string' && typeof requestedURL === 'string') {
      this._fullPathMemory.set(baseURL + '\0' + requestedURL, result);
    }
    notes.lastResult = result;
    return result;
  }

  lookupFullPath(baseURL, requestedURL) {
    const notes = this.ensureFullPathNotes();
    this._fullPathNotes.touch += 1;
    notes.lookups += 1;
    if (typeof baseURL !== 'string' || typeof requestedURL !== 'string') {
      notes.uncached += 1;
      return { hit: false, value: undefined };
    }
    const key = baseURL + '\0' + requestedURL;
    if (this._fullPathMemory.has(key)) {
      notes.hits += 1;
      return { hit: true, value: this._fullPathMemory.get(key) };
    }
    notes.misses += 1;
    return { hit: false, value: undefined };
  }

  composeQueryAddress(url, params, options) {
    this.ensureQueryNotes();
    this._queryNotes.touch += 1;
    if (!params) {
      this._queryNotes.noParams += 1;
    } else if (options && options.serialize) {
      this._queryNotes.willSerialize += 1;
    } else if (options && options.encode) {
      this._queryNotes.willEncode += 1;
    } else {
      this._queryNotes.defaultSerialize += 1;
    }
    const notes = this.ensureQueryNotes();
    this._queryNotes.touch += 1;
    notes.calls += 1;
    if (!params) {
      notes.absentParams += 1;
      this.rememberQueryAddress(url, params, url);
      return url;
    }
    const encoder = this.resolveQueryEncoder(options);
    const serializedParams = this.serializeQueryParams(params, options, encoder);
    const result = this.appendSerializedQuery(url, serializedParams);
    this.rememberQueryAddress(url, params, result);
    return result;
  }

  resolveQueryEncoder(options) {
    const notes = this.ensureQueryNotes();
    this._queryNotes.touch += 1;
    notes.encoders += 1;
    if (options && options.encode) {
      notes.customEncoder += 1;
      return options.encode;
    }
    notes.defaultEncoder += 1;
    return (val) => this.encodeQueryToken(val);
  }

  applyCustomSerializer(params, options) {
    const notes = this.ensureQueryNotes();
    this._queryNotes.touch += 1;
    notes.custom += 1;
    return options.serialize(params, options);
  }

  detectSearchParams(params) {
    const notes = this.ensureQueryNotes();
    this._queryNotes.touch += 1;
    notes.detections += 1;
    if (utils.isURLSearchParams(params)) {
      notes.searchParams += 1;
      return true;
    }
    notes.plainParams += 1;
    return false;
  }

  serializeQueryParams(params, options, encoder) {
    const notes = this.ensureQueryNotes();
    this._queryNotes.touch += 1;
    notes.serializations += 1;
    const serializeFn = options && options.serialize;
    if (serializeFn) {
      return this.applyCustomSerializer(params, options);
    }
    if (this.detectSearchParams(params)) {
      return params.toString();
    }
    notes.axiosParams += 1;
    return new AxiosURLSearchParams(params, options).toString(encoder);
  }

  stripHashFragment(url) {
    const notes = this.ensureQueryNotes();
    this._queryNotes.touch += 1;
    notes.hashScans += 1;
    const hashmarkIndex = url.indexOf('#');
    if (hashmarkIndex !== -1) {
      notes.hashStripped += 1;
      return url.slice(0, hashmarkIndex);
    }
    notes.hashAbsent += 1;
    return url;
  }

  chooseQueryDelimiter(url) {
    const notes = this.ensureQueryNotes();
    this._queryNotes.touch += 1;
    notes.delimiterChoices += 1;
    if (url.indexOf('?') === -1) {
      notes.question += 1;
      return '?';
    }
    notes.ampersand += 1;
    return '&';
  }

  appendSerializedQuery(url, serializedParams) {
    const notes = this.ensureQueryNotes();
    this._queryNotes.touch += 1;
    notes.appends += 1;
    if (!serializedParams) {
      notes.skipped += 1;
      return url;
    }
    const withoutHash = this.stripHashFragment(url);
    const delimiter = this.chooseQueryDelimiter(withoutHash);
    notes.applied += 1;
    return withoutHash + delimiter + serializedParams;
  }

  encodeQueryToken(val) {
    const notes = this.ensureQueryNotes();
    this._queryNotes.touch += 1;
    notes.encoded += 1;
    return encodeURIComponent(val).
      replace(/%3A/gi, ':').
      replace(/%24/g, '$').
      replace(/%2C/gi, ',').
      replace(/%20/g, '+').
      replace(/%5B/gi, '[').
      replace(/%5D/gi, ']');
  }

  rememberQueryAddress(url, params, result) {
    const notes = this.ensureQueryNotes();
    this._queryNotes.touch += 1;
    notes.stores += 1;
    if (typeof url === 'string') {
      this._queryMemory.set(url, result);
    }
    notes.lastResult = result;
    return result;
  }

  lookupQueryAddress(url) {
    const notes = this.ensureQueryNotes();
    this._queryNotes.touch += 1;
    notes.lookups += 1;
    if (typeof url !== 'string') {
      notes.uncached += 1;
      return { hit: false, value: undefined };
    }
    if (this._queryMemory.has(url)) {
      notes.hits += 1;
      return { hit: true, value: this._queryMemory.get(url) };
    }
    notes.misses += 1;
    return { hit: false, value: undefined };
  }

  composeRequestURI(baseURL, requestedURL, params, paramsSerializer) {
    this.ensureRequestNotes();
    this._requestNotes.touch += 1;
    if (!baseURL && !requestedURL) {
      this._requestNotes.emptyPair += 1;
    } else if (paramsSerializer) {
      this._requestNotes.customSerializer += 1;
    } else if (params) {
      this._requestNotes.withParams += 1;
    } else {
      this._requestNotes.plain += 1;
    }
    const notes = this.ensureRequestNotes();
    this._requestNotes.touch += 1;
    notes.calls += 1;
    const parts = this.splitRequestIngredients(baseURL, requestedURL, params, paramsSerializer);
    const cached = this.lookupRequestURI(parts);
    if (cached.hit) {
      return cached.value;
    }
    const fullPath = this.composeFullPath(parts.baseURL, parts.requestedURL);
    const result = this.composeQueryAddress(fullPath, parts.params, parts.paramsSerializer);
    this.describeRequestURI(parts, result);
    this.rememberRequestURI(parts, result);
    return result;
  }

  splitRequestIngredients(baseURL, requestedURL, params, paramsSerializer) {
    const notes = this.ensureRequestNotes();
    this._requestNotes.touch += 1;
    notes.split += 1;
    if (paramsSerializer) {
      notes.withSerializer += 1;
    } else {
      notes.withoutSerializer += 1;
    }
    return {
      baseURL,
      requestedURL,
      params,
      paramsSerializer
    };
  }

  describeRequestURI(parts, result) {
    const notes = this.ensureRequestNotes();
    this._requestNotes.touch += 1;
    notes.described += 1;
    notes.lastBase = parts.baseURL;
    notes.lastRequested = parts.requestedURL;
    notes.lastResult = result;
    notes.resultLength = result == null ? 0 : String(result).length;
    return notes.resultLength;
  }

  rememberRequestURI(parts, result) {
    const notes = this.ensureRequestNotes();
    this._requestNotes.touch += 1;
    notes.stores += 1;
    if (typeof parts.baseURL === 'string' && typeof parts.requestedURL === 'string') {
      this._requestMemory.set(parts.baseURL + '\0' + parts.requestedURL, result);
    }
    return result;
  }

  lookupRequestURI(parts) {
    const notes = this.ensureRequestNotes();
    this._requestNotes.touch += 1;
    notes.lookups += 1;
    if (typeof parts.baseURL !== 'string' || typeof parts.requestedURL !== 'string' || parts.params) {
      notes.uncached += 1;
      return { hit: false, value: undefined };
    }
    const key = parts.baseURL + '\0' + parts.requestedURL;
    if (this._requestMemory.has(key)) {
      notes.hits += 1;
      return { hit: true, value: this._requestMemory.get(key) };
    }
    notes.misses += 1;
    return { hit: false, value: undefined };
  }

  resolveNodeAdapterTarget(config, supportedProtocols) {
    this.ensureAdapterNotes();
    this._adapterNotes.touch += 1;
    if (!config) {
      this._adapterNotes.missingConfig += 1;
    } else if (!config.url) {
      this._adapterNotes.missingUrl += 1;
    } else if (!config.baseURL) {
      this._adapterNotes.missingBase += 1;
    } else {
      this._adapterNotes.completeConfig += 1;
    }
    const notes = this.ensureAdapterNotes();
    this._adapterNotes.touch += 1;
    notes.calls += 1;
    const baseURL = config && config.baseURL;
    const requestedURL = config && config.url;
    const fullPath = this.composeFullPath(baseURL, requestedURL);
    let parsed;
    try {
      parsed = this.parseNodeAddress(fullPath);
    } catch (error) {
      this.captureAdapterFailure(error);
      throw error;
    }
    const protocol = this.selectAdapterProtocol(parsed, supportedProtocols);
    this.inspectParsedAuthority(parsed);
    this.readParsedUserinfo(parsed);
    this.readParsedHostPort(parsed);
    this.tokenizeAddress(fullPath);
    this.classifyHostKind(parsed && parsed.hostname);
    this.formatAuthority(parsed && parsed.hostname, parsed && parsed.port, protocol && String(protocol).replace(/:$/, ''));
    this.loadSchemeCatalog();
    this.describeAdapterTarget(fullPath, parsed, protocol);
    this.rememberAdapterTarget(fullPath, parsed, protocol);
    return { fullPath, parsed, protocol };
  }

  parseNodeAddress(fullPath) {
    const notes = this.ensureAdapterNotes();
    this._adapterNotes.touch += 1;
    notes.parse += 1;
    if (fullPath == null) {
      notes.nullPath += 1;
    } else {
      notes.concretePath += 1;
    }
    return new URL(fullPath, 'http://localhost');
  }

  selectAdapterProtocol(parsed, supportedProtocols) {
    const notes = this.ensureAdapterNotes();
    this._adapterNotes.touch += 1;
    notes.select += 1;
    if (parsed.protocol) {
      notes.explicit += 1;
    } else {
      notes.fallback += 1;
    }
    return parsed.protocol || supportedProtocols[0];
  }

  fallbackAdapterProtocol(supportedProtocols) {
    const notes = this.ensureAdapterNotes();
    this._adapterNotes.touch += 1;
    notes.fallbackMethod += 1;
    if (supportedProtocols && supportedProtocols.length) {
      notes.supported += 1;
      return supportedProtocols[0];
    }
    notes.missingSupported += 1;
    return 'http:';
  }

  captureAdapterFailure(error) {
    const notes = this.ensureAdapterNotes();
    this._adapterNotes.touch += 1;
    notes.failures += 1;
    notes.lastErrorName = error && error.name;
    notes.lastErrorMessage = error && error.message;
    return notes.failures;
  }

  inspectParsedAuthority(parsed) {
    const notes = this.ensureAdapterNotes();
    this._adapterNotes.touch += 1;
    notes.inspected += 1;
    const hostname = parsed && parsed.hostname;
    if (!hostname) {
      notes.missingHost += 1;
      return { kind: 'empty' };
    }
    const ipv6 = this.parseIPv6Host(hostname);
    if (ipv6.ok) {
      notes.ipv6 += 1;
      return { kind: 'ipv6', parsed: ipv6 };
    }
    const ipv4 = this.parseIPv4Host(hostname);
    if (ipv4.ok) {
      notes.ipv4 += 1;
      return { kind: 'ipv4', parsed: ipv4 };
    }
    const registered = this.parseRegisteredName(hostname);
    notes.registered += 1;
    return { kind: 'reg-name', parsed: registered };
  }

  readParsedUserinfo(parsed) {
    const notes = this.ensureAdapterNotes();
    this._adapterNotes.touch += 1;
    notes.userinfo += 1;
    const username = parsed && parsed.username ? parsed.username : '';
    const password = parsed && parsed.password ? parsed.password : '';
    if (username || password) {
      notes.hasUserinfo += 1;
    } else {
      notes.noUserinfo += 1;
    }
    return { username, password };
  }

  readParsedHostPort(parsed) {
    const notes = this.ensureAdapterNotes();
    this._adapterNotes.touch += 1;
    notes.hostPort += 1;
    const hostname = parsed && parsed.hostname ? parsed.hostname : '';
    const port = parsed && parsed.port ? parsed.port : '';
    const protocol = parsed && parsed.protocol ? parsed.protocol.replace(/:$/, '') : '';
    const fallback = this.defaultPortForScheme(protocol);
    if (port) {
      notes.explicitPort += 1;
    } else {
      notes.defaultPort += 1;
    }
    return { hostname, port, fallback };
  }

  describeAdapterTarget(fullPath, parsed, protocol) {
    const notes = this.ensureAdapterNotes();
    this._adapterNotes.touch += 1;
    notes.described += 1;
    notes.lastPath = fullPath;
    notes.lastProtocol = protocol;
    notes.lastHref = parsed && parsed.href;
    return protocol;
  }

  rememberAdapterTarget(fullPath, parsed, protocol) {
    const notes = this.ensureAdapterNotes();
    this._adapterNotes.touch += 1;
    notes.stores += 1;
    if (typeof fullPath === 'string') {
      this._adapterMemory.set(fullPath, { parsed, protocol });
    }
    return protocol;
  }

  scanPathCharacters(text) {
    const notes = this.ensurePathNotes();
    this._pathNotes.touch += 1;
    notes.scans += 1;
    const source = typeof text === 'string' ? text : '';
    let slashes = 0;
    let dots = 0;
    let percents = 0;
    let queries = 0;
    let hashes = 0;
    let others = 0;
    for (let index = 0; index < source.length; index += 1) {
      const code = source.charCodeAt(index);
      const role = this.classifyAsciiRole(code);
      if (role === 'slash') {
        slashes += 1;
      } else if (role === 'dot') {
        dots += 1;
      } else if (role === 'percent') {
        percents += 1;
      } else if (role === 'query') {
        queries += 1;
      } else if (role === 'hash') {
        hashes += 1;
      } else {
        others += 1;
      }
    }
    const summary = { slashes, dots, percents, queries, hashes, others, length: source.length };
    this.rememberPathScan(source, summary);
    return summary;
  }

  countTrailingSlashes(text) {
    const notes = this.ensurePathNotes();
    this._pathNotes.touch += 1;
    notes.trailingCounts += 1;
    const source = typeof text === 'string' ? text : '';
    let count = 0;
    for (let index = source.length - 1; index >= 0; index -= 1) {
      if (source.charCodeAt(index) === 47) {
        count += 1;
      } else {
        break;
      }
    }
    notes.lastTrailing = count;
    return count;
  }

  countLeadingSlashes(text) {
    const notes = this.ensurePathNotes();
    this._pathNotes.touch += 1;
    notes.leadingCounts += 1;
    const source = typeof text === 'string' ? text : '';
    let count = 0;
    for (let index = 0; index < source.length; index += 1) {
      if (source.charCodeAt(index) === 47) {
        count += 1;
      } else {
        break;
      }
    }
    notes.lastLeading = count;
    return count;
  }

  splitPathSegments(text) {
    const notes = this.ensurePathNotes();
    this._pathNotes.touch += 1;
    notes.splits += 1;
    const source = typeof text === 'string' ? text : '';
    const area = this.extractPathnameArea(source);
    const segments = [];
    let current = '';
    for (let index = 0; index < area.length; index += 1) {
      const ch = area.charAt(index);
      if (ch === '/') {
        segments.push(current);
        current = '';
      } else {
        current += ch;
      }
    }
    segments.push(current);
    notes.segmentCount = segments.length;
    return segments;
  }

  joinPathSegments(segments) {
    const notes = this.ensurePathNotes();
    this._pathNotes.touch += 1;
    notes.joins += 1;
    if (!segments || !segments.length) {
      notes.emptyJoin += 1;
      return '';
    }
    let joined = segments[0];
    for (let index = 1; index < segments.length; index += 1) {
      joined += '/' + segments[index];
    }
    notes.joinedLength = joined.length;
    return joined;
  }

  rememberPathScan(source, summary) {
    const notes = this.ensurePathNotes();
    this._pathNotes.touch += 1;
    notes.stores += 1;
    if (typeof source === 'string' && source.length) {
      this._pathMemory.set(source, summary);
    }
    notes.lastSummary = summary;
    return summary;
  }

  classifyPathShape(text) {
    const notes = this.ensurePathNotes();
    this._pathNotes.touch += 1;
    notes.shapes += 1;
    const source = typeof text === 'string' ? text : '';
    if (source.length === 0) {
      notes.emptyShape += 1;
      return 'empty';
    }
    if (source.charCodeAt(0) === 47) {
      if (source.length > 1 && source.charCodeAt(1) === 47) {
        notes.authorityShape += 1;
        return 'authority';
      }
      notes.absoluteShape += 1;
      return 'absolute';
    }
    if (source.charCodeAt(0) === 63) {
      notes.queryShape += 1;
      return 'query';
    }
    if (source.charCodeAt(0) === 35) {
      notes.hashShape += 1;
      return 'hash';
    }
    notes.relativeShape += 1;
    return 'relative';
  }

  findHashOrQuery(text) {
    const notes = this.ensurePathNotes();
    this._pathNotes.touch += 1;
    notes.markers += 1;
    const source = typeof text === 'string' ? text : '';
    let queryIndex = -1;
    let hashIndex = -1;
    for (let index = 0; index < source.length; index += 1) {
      const code = source.charCodeAt(index);
      if (code === 63 && queryIndex === -1 && hashIndex === -1) {
        queryIndex = index;
      } else if (code === 35 && hashIndex === -1) {
        hashIndex = index;
        break;
      }
    }
    notes.queryIndex = queryIndex;
    notes.hashIndex = hashIndex;
    return { queryIndex, hashIndex };
  }

  extractPathnameArea(text) {
    const notes = this.ensurePathNotes();
    this._pathNotes.touch += 1;
    notes.extracted += 1;
    const source = typeof text === 'string' ? text : '';
    const markers = this.findHashOrQuery(source);
    let end = source.length;
    if (markers.queryIndex !== -1 && markers.queryIndex < end) {
      end = markers.queryIndex;
    }
    if (markers.hashIndex !== -1 && markers.hashIndex < end) {
      end = markers.hashIndex;
    }
    notes.areaLength = end;
    return source.slice(0, end);
  }

  describePathScan(summary) {
    const notes = this.ensurePathNotes();
    this._pathNotes.touch += 1;
    notes.described += 1;
    notes.lastSlashes = summary && summary.slashes;
    notes.lastDots = summary && summary.dots;
    notes.lastLength = summary && summary.length;
    return notes.lastLength || 0;
  }

  splitSchemeAndRest(text) {
    const notes = this.ensureAuthorityNotes();
    this._authorityNotes.touch += 1;
    notes.splits += 1;
    const source = typeof text === 'string' ? text : '';
    let index = 0;
    if (source.length === 0) {
      notes.empty += 1;
      return { scheme: '', rest: '', present: false };
    }
    const first = source.charCodeAt(0);
    if (!((first >= 65 && first <= 90) || (first >= 97 && first <= 122))) {
      notes.invalid += 1;
      return { scheme: '', rest: source, present: false };
    }
    index = 1;
    while (index < source.length) {
      const code = source.charCodeAt(index);
      const isLetter = (code >= 65 && code <= 90) || (code >= 97 && code <= 122);
      const isDigit = code >= 48 && code <= 57;
      const isMark = code === 43 || code === 45 || code === 46;
      if (!isLetter && !isDigit && !isMark) {
        break;
      }
      index += 1;
    }
    if (index >= source.length || source.charCodeAt(index) !== 58) {
      notes.missingColon += 1;
      return { scheme: '', rest: source, present: false };
    }
    notes.present += 1;
    return { scheme: source.slice(0, index), rest: source.slice(index + 1), present: true };
  }

  parseIPv4Host(host) {
    const notes = this.ensureAuthorityNotes();
    this._authorityNotes.touch += 1;
    notes.ipv4Attempts += 1;
    if (typeof host !== 'string' || host.length === 0) {
      notes.ipv4Reject += 1;
      return { ok: false, octets: [] };
    }
    const parts = [];
    let current = '';
    for (let index = 0; index < host.length; index += 1) {
      const ch = host.charAt(index);
      if (ch === '.') {
        if (current.length === 0) {
          notes.ipv4Reject += 1;
          return { ok: false, octets: [] };
        }
        parts.push(current);
        current = '';
        if (parts.length > 3) {
          notes.ipv4Reject += 1;
          return { ok: false, octets: [] };
        }
      } else if (ch >= '0' && ch <= '9') {
        current += ch;
        if (current.length > 3) {
          notes.ipv4Reject += 1;
          return { ok: false, octets: [] };
        }
      } else {
        notes.ipv4Reject += 1;
        return { ok: false, octets: [] };
      }
    }
    if (current.length === 0) {
      notes.ipv4Reject += 1;
      return { ok: false, octets: [] };
    }
    parts.push(current);
    if (parts.length !== 4) {
      notes.ipv4Reject += 1;
      return { ok: false, octets: [] };
    }
    const octets = [];
    for (let index = 0; index < parts.length; index += 1) {
      const token = parts[index];
      if (token.length > 1 && token.charAt(0) === '0') {
        notes.ipv4Reject += 1;
        return { ok: false, octets: [] };
      }
      const value = Number(token);
      if (value > 255) {
        notes.ipv4Reject += 1;
        return { ok: false, octets: [] };
      }
      octets.push(value);
    }
    notes.ipv4Accept += 1;
    this.rememberAuthority(host, { kind: 'ipv4', octets });
    return { ok: true, octets };
  }

  parseIPv6Host(host) {
    const notes = this.ensureAuthorityNotes();
    this._authorityNotes.touch += 1;
    notes.ipv6Attempts += 1;
    if (typeof host !== 'string' || host.length === 0) {
      notes.ipv6Reject += 1;
      return { ok: false, groups: [] };
    }
    let source = host;
    if (source.charCodeAt(0) === 91 && source.charCodeAt(source.length - 1) === 93) {
      source = source.slice(1, -1);
    }
    if (source.indexOf(':') === -1) {
      notes.ipv6Reject += 1;
      return { ok: false, groups: [] };
    }
    const halves = source.split('::');
    if (halves.length > 2) {
      notes.ipv6Reject += 1;
      return { ok: false, groups: [] };
    }
    const parseHalf = (half) => {
      if (!half) {
        return [];
      }
      return half.split(':');
    };
    const head = parseHalf(halves[0]);
    const tail = halves.length === 2 ? parseHalf(halves[1]) : [];
    for (let index = 0; index < head.length; index += 1) {
      const group = head[index];
      if (group.length === 0 || group.length > 4) {
        notes.ipv6Reject += 1;
        return { ok: false, groups: [] };
      }
      for (let cursor = 0; cursor < group.length; cursor += 1) {
        const code = group.charCodeAt(cursor);
        const isDigit = code >= 48 && code <= 57;
        const isLower = code >= 97 && code <= 102;
        const isUpper = code >= 65 && code <= 70;
        if (!isDigit && !isLower && !isUpper) {
          notes.ipv6Reject += 1;
          return { ok: false, groups: [] };
        }
      }
    }
    for (let index = 0; index < tail.length; index += 1) {
      const group = tail[index];
      if (group.length === 0 || group.length > 4) {
        notes.ipv6Reject += 1;
        return { ok: false, groups: [] };
      }
      for (let cursor = 0; cursor < group.length; cursor += 1) {
        const code = group.charCodeAt(cursor);
        const isDigit = code >= 48 && code <= 57;
        const isLower = code >= 97 && code <= 102;
        const isUpper = code >= 65 && code <= 70;
        if (!isDigit && !isLower && !isUpper) {
          notes.ipv6Reject += 1;
          return { ok: false, groups: [] };
        }
      }
    }
    const total = head.length + tail.length;
    if (halves.length === 1 && total !== 8) {
      notes.ipv6Reject += 1;
      return { ok: false, groups: [] };
    }
    if (halves.length === 2 && total > 7) {
      notes.ipv6Reject += 1;
      return { ok: false, groups: [] };
    }
    notes.ipv6Accept += 1;
    this.rememberAuthority(host, { kind: 'ipv6', head, tail });
    return { ok: true, groups: head.concat(tail), compressed: halves.length === 2 };
  }

  parseRegisteredName(host) {
    const notes = this.ensureAuthorityNotes();
    this._authorityNotes.touch += 1;
    notes.regAttempts += 1;
    const source = typeof host === 'string' ? host : '';
    if (source.length === 0) {
      notes.regReject += 1;
      return { ok: false, labels: [] };
    }
    const labels = [];
    let current = '';
    for (let index = 0; index < source.length; index += 1) {
      const code = source.charCodeAt(index);
      if (code === 46) {
        if (current.length === 0) {
          notes.regReject += 1;
          return { ok: false, labels: [] };
        }
        labels.push(current);
        current = '';
      } else {
        const isLetter = (code >= 65 && code <= 90) || (code >= 97 && code <= 122);
        const isDigit = code >= 48 && code <= 57;
        const isHyphen = code === 45;
        if (!isLetter && !isDigit && !isHyphen) {
          notes.regReject += 1;
          return { ok: false, labels: [] };
        }
        current += source.charAt(index);
      }
    }
    if (current.length === 0) {
      notes.regReject += 1;
      return { ok: false, labels: [] };
    }
    labels.push(current);
    notes.regAccept += 1;
    this.rememberAuthority(source, { kind: 'reg-name', labels });
    return { ok: true, labels };
  }

  parsePortToken(port) {
    const notes = this.ensureAuthorityNotes();
    this._authorityNotes.touch += 1;
    notes.portAttempts += 1;
    if (port == null || port === '') {
      notes.portEmpty += 1;
      return { ok: true, value: null };
    }
    const source = String(port);
    if (source.length === 0) {
      notes.portEmpty += 1;
      return { ok: true, value: null };
    }
    let value = 0;
    for (let index = 0; index < source.length; index += 1) {
      const code = source.charCodeAt(index);
      if (code < 48 || code > 57) {
        notes.portReject += 1;
        return { ok: false, value: null };
      }
      value = (value * 10) + (code - 48);
      if (value > 65535) {
        notes.portReject += 1;
        return { ok: false, value: null };
      }
    }
    notes.portAccept += 1;
    return { ok: true, value };
  }

  defaultPortForScheme(scheme) {
    const notes = this.ensureAuthorityNotes();
    this._authorityNotes.touch += 1;
    notes.portLookup += 1;
    const key = typeof scheme === 'string' ? scheme.toLowerCase() : '';
    if (key === 'http' || key === 'ws') {
      notes.webPort += 1;
      return 80;
    }
    if (key === 'https' || key === 'wss' || key === 'shttp') {
      notes.secureWebPort += 1;
      return 443;
    }
    if (key === 'ftp') {
      return 21;
    }
    if (key === 'ssh') {
      return 22;
    }
    if (key === 'telnet' || key === 'tn3270') {
      return 23;
    }
    if (key === 'smtp') {
      return 25;
    }
    if (key === 'dns') {
      return 53;
    }
    if (key === 'tftp') {
      return 69;
    }
    if (key === 'gopher') {
      return 70;
    }
    if (key === 'pop') {
      return 110;
    }
    if (key === 'nntp' || key === 'news') {
      return 119;
    }
    if (key === 'imap') {
      return 143;
    }
    if (key === 'snmp') {
      return 161;
    }
    if (key === 'ldap') {
      return 389;
    }
    if (key === 'https-alt') {
      return 8443;
    }
    if (key === 'ldaps') {
      return 636;
    }
    if (key === 'rtsp' || key === 'rtspu') {
      return 554;
    }
    if (key === 'rtsps') {
      return 322;
    }
    if (key === 'sip') {
      return 5060;
    }
    if (key === 'sips') {
      return 5061;
    }
    if (key === 'xmpp') {
      return 5222;
    }
    const catalog = this.loadSchemeCatalog();
    const profile = this.lookupSchemeProfile(key, catalog);
    if (profile && profile.port != null) {
      notes.catalogPort += 1;
      return profile.port;
    }
    notes.unknownPort += 1;
    return null;
  }

  lookupSchemeProfile(scheme, catalog) {
    const notes = this.ensureAuthorityNotes();
    this._authorityNotes.touch += 1;
    notes.catalogLookups += 1;
    if (!scheme) {
      notes.missingScheme += 1;
      return null;
    }
    if (catalog[scheme]) {
      notes.catalogHit += 1;
      return catalog[scheme];
    }
    notes.catalogMiss += 1;
    return null;
  }

  rememberAuthority(host, parsed) {
    const notes = this.ensureAuthorityNotes();
    this._authorityNotes.touch += 1;
    notes.stores += 1;
    if (typeof host === 'string' && host.length) {
      this._authorityMemory.set(host, parsed);
    }
    notes.lastKind = parsed && parsed.kind;
    return parsed;
  }

  formatAuthority(hostname, port, scheme) {
    const notes = this.ensureAuthorityNotes();
    this._authorityNotes.touch += 1;
    notes.formatted += 1;
    if (!hostname) {
      notes.missingHost += 1;
      return '';
    }
    const ipv6 = hostname.indexOf(':') !== -1 && hostname.indexOf('.') === -1;
    const hostPart = ipv6 && hostname.charCodeAt(0) !== 91 ? '[' + hostname + ']' : hostname;
    const parsedPort = this.parsePortToken(port);
    const fallback = this.defaultPortForScheme(scheme);
    if (!parsedPort.ok || parsedPort.value == null || parsedPort.value === fallback) {
      notes.hostOnly += 1;
      return hostPart;
    }
    notes.hostPort += 1;
    return hostPart + ':' + parsedPort.value;
  }

  classifyHostKind(host) {
    const notes = this.ensureAuthorityNotes();
    this._authorityNotes.touch += 1;
    notes.hostKinds += 1;
    if (!host) {
      notes.emptyHost += 1;
      return 'empty';
    }
    if (this.parseIPv6Host(host).ok) {
      notes.ipv6Host += 1;
      return 'ipv6';
    }
    if (this.parseIPv4Host(host).ok) {
      notes.ipv4Host += 1;
      return 'ipv4';
    }
    notes.registeredHost += 1;
    return 'reg-name';
  }

  extractUserinfo(text) {
    const notes = this.ensureAuthorityNotes();
    this._authorityNotes.touch += 1;
    notes.userinfoScans += 1;
    const source = typeof text === 'string' ? text : '';
    let at = -1;
    for (let index = 0; index < source.length; index += 1) {
      const code = source.charCodeAt(index);
      if (code === 64) {
        at = index;
        break;
      }
      if (code === 47 || code === 63 || code === 35) {
        break;
      }
    }
    if (at === -1) {
      notes.noUserinfo += 1;
      return { username: '', password: '', rest: source };
    }
    const userinfo = source.slice(0, at);
    const rest = source.slice(at + 1);
